def find_repeats(a,b,k=25,label=""):
    # exact k-mer matches, extend
    d={}
    hits=[]
    for i in range(len(a)-k+1):
        d.setdefault(a[i:i+k],[]).append(i)
    for j in range(len(b)-k+1):
        km=b[j:j+k]
        if km in d:
            for i in d[km]:
                hits.append((i,j))
    # merge overlapping diagonal hits
    merged={}
    for i,j in hits:
        diag=i-j
        merged.setdefault(diag,[]).append((i,j))
    out=[]
    for diag,hl in merged.items():
        hl.sort()
        # group consecutive-ish
        groups=[]
        cur=[hl[0]]
        for p in hl[1:]:
            if p[1]-cur[-1][1]<=k:
                cur.append(p)
            else:
                groups.append(cur); cur=[p]
        groups.append(cur)
        for g in groups:
            i0=g[0][0]; i1=g[-1][0]+k
            out.append((i0,i1,diag))
    return out

# self comparison forward vs forward
rep = find_repeats(seq,seq,k=30)
print("Forward direct repeats len>=30:")
seen=set()
