import random, re
seq="".join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
n=len(seq)
stops={'TAA','TAG','TGA'}
comp=str.maketrans("ACGT","TGCA")
def revcomp(s): return s.translate(comp)[::-1]
r=revcomp(seq)

def longest_orf_aa(s):
    best=0; tot=0; lens=[]
    for f in range(3):
        run=0
        for i in range(f,len(s)-2,3):
            if s[i:i+3] in stops:
                lens.append(run); run=0
            else: run+=1
        lens.append(run)
    return lens

lens_obs = longest_orf_aa(seq)+longest_orf_aa(r)
print("observed ORF lengths (aa):", sorted(lens_obs,reverse=True)[:10])
print("observed n >=90aa:", sum(1 for x in lens_obs if x>=90), " >=150:", sum(1 for x in lens_obs if x>=150))

def mono_shuffle():
    L=list(seq); random.shuffle(L); return "".join(L)

def dinuc_shuffle(s, nswap=None):
    s=list(s)
    if nswap is None: nswap=10*len(s)
    for _ in range(nswap):
        i=random.randrange(0,len(s)-1); j=random.randrange(0,len(s)-1)
        # Altschul-Erikson: swap letters at i+1, j+1 where s[i]==s[j]
        if s[i]==s[j]:
            if random.random()<0.5:
                s[i+1],s[j+1]=s[j+1],s[i+1]
    return "".join(s)

random.seed(1)
import statistics
for name,shuf in [("mono",mono_shuffle),("dinuc",lambda:dinuc_shuffle(seq))]:
    cnt90=[];cnt150=[];mx=[]
    for t in range(30):
        s=shuf()
        ls=longest_orf_aa(s)+longest_orf_aa(revcomp(s))
        cnt90.append(sum(1 for x in ls if x>=90))
        cnt150.append(sum(1 for x in ls if x>=150))
        mx.append(max(ls))
    print(f"{name}: mean #ORF>=90 {statistics.mean(cnt90):.1f} (obs {sum(1 for x in lens_obs if x>=90)}), mean #>=150 {statistics.mean(cnt150):.1f} (obs {sum(1 for x in lens_obs if x>=150)}), mean max {statistics.mean(mx):.0f} (obs {max(lens_obs)})")
