seq="".join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
n=len(seq)
comp=str.maketrans("ACGT","TGCA")
def revcomp(s): return s.translate(comp)[::-1]

for k in [8,9,10,11,12,13,14,15]:
    idx=defaultdict(list)
    for i in range(n-k+1): idx[seq[i:i+k]].append(i)
    rep=[(m,v) for m,v in idx.items() if len(v)>1]
    print(f"k={k}: {len(rep)} repeated k-mers")
    for m,v in rep[:8]:
        print("   ",m,v)

# inverted repeats with mismatch tolerance, k=10 seeds
k=10
idx=defaultdict(list)
for i in range(n-k+1): idx[seq[i:i+k]].append(i)
invs=set()
r=revcomp(seq)
for j in range(n-k+1):
    km=r[j:j+k]
    if km in idx:
        for i in idx[km]:
            p=n-j-k
            invs.add((min(i,p),max(i,p)))
print("\ninverted-repeat seeds k=10:",len(invs))
# extend each with mismatch tolerance
res=[]
for a,b in invs:
    if b-a < k: continue
    x=0; mm=0
    while a+x<n and b-1-x>=0:
        if seq[a+x]==seq[b-1-x].translate(comp): pass
        else:
            mm+=1
            if mm>4: break
        x+=1
    if x>=25:
        res.append((a,b-1,x,mm))
for a,b,L,mm in sorted(res,key=lambda t:-t[2])[:15]:
    print(f"  IR {a+1}-{b+1} stemlen~{L} mismatches~{mm}")
